window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[10]={"id":"010","numero":10,"titre":"Approches transversales du corps","objectifs":[{"id":"10-1","rang":"A","rubrique":"Définition","titre":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","contenu":"<p>En sciences humaines, le <strong><span class=\"kw-def\">corps</span></strong> est un <strong><span class=\"kw-def\">objet d'étude multidimensionnel</span></strong> abordé par une <strong><span class=\"kw-def\">approche transversale</span></strong> propre aux <span class=\"kw-def\">sciences humaines et sociales</span> (SHS). Sa représentation est une <strong><span class=\"kw-def\">construction sociale</span></strong> qui s'adapte aux contraintes posées par <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">traditions culturelles</span> et le <span class=\"kw-etio\">milieu naturel</span>.</p>\n\n<h4 class=\"kw-def\">Disciplines mobilisées (approche transversale)</h4>\n<ul>\n  <li><span class=\"kw-def\">Histoire</span></li>\n  <li><span class=\"kw-def\">Sociologie</span></li>\n  <li><span class=\"kw-def\">Anthropologie</span></li>\n  <li><span class=\"kw-def\">Philosophie</span></li>\n  <li><span class=\"kw-def\">Littérature</span></li>\n</ul>\n\n<h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> cinq dimensions humaines du corps</h4>\n<table >\n  <thead><tr><th>Dimension</th><th>Contenu</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Alimentation</span></strong></td><td>Choix des aliments adaptés à l'homme ; manière de se nourrir</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Activité physique</span></strong></td><td>Rapport du corps au mouvement et à la <span class=\"kw-etio\">sédentarité</span></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Genre</span></strong></td><td>Question de l'<span class=\"kw-def\">identité</span> et de l'<span class=\"kw-def\">identité sexuée</span></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Procréation</span></strong></td><td>Rapport du corps à la reproduction</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Normes esthétiques</span></strong></td><td>Standards de beauté et règles corporelles</td></tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-warn\">⚠️ <span class=\"kw-clinique\">Les</span> <strong>représentations d'un corps en bonne santé</strong> <span class=\"kw-alerte\">changent selon les époques</span> : il n'existe pas de norme corporelle universelle, mais une construction sociale variable selon les cultures.</div>\n\n<h4 class=\"kw-def\">Alimentation : un fait social</h4>\n<p>L'<strong><span class=\"kw-def\">acte de manger</span></strong> reconstruit des <span class=\"kw-def\">logiques sociales</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">identités d'un groupe</span>. L'alimentation est au cœur d'un dispositif <span class=\"kw-def\">social</span>, <span class=\"kw-def\">symbolique</span> et <span class=\"kw-def\">économique</span> :</p>\n<ul>\n  <li><span class=\"kw-etio\">Interdits alimentaires</span> dans plusieurs traditions religieuses</li>\n  <li><span class=\"kw-etio\">Régimes de santé</span> liés aux âges de la vie (enfance, vieillesse)</li>\n  <li>Impact de certaines nourritures sur la <span class=\"kw-clinique\">sphère émotionnelle et affective</span></li>\n  <li>Importance de la <span class=\"kw-def\">gastronomie</span> dans <span class=\"kw-clinique\">les</span> interactions sociales</li>\n</ul>\n<p><span class=\"kw-clinique\">Évolution</span> selon <span class=\"kw-clinique\">les</span> époques : à la <span class=\"kw-chiffre\">Renaissance</span>, l'<span class=\"kw-def\">embonpoint</span> = signe de bonne santé ; à partir des <span class=\"kw-chiffre\">années 1960-1970</span>, le <strong><span class=\"kw-clinique\">surpoids / obésité</span></strong> devient un <strong><span class=\"kw-def\">problème majeur de santé publique</span></strong>. Cette bascule est liée à l'<span class=\"kw-etio\">industrialisation</span> et à l'<span class=\"kw-etio\">urbanisation</span> (mode de vie <span class=\"kw-etio\">sédentaire</span>, alimentation plus riche).</p>\n\n<h4 class=\"kw-def\">Normes esthétiques</h4>\n<ul>\n  <li>Reflètent des <span class=\"kw-def\">différences sociales</span> et <span class=\"kw-def\">culturelles</span></li>\n  <li><span class=\"kw-def\">Transformations volontaires</span> du corps : tatouages, piercings, scarifications — fonctions variables selon <span class=\"kw-clinique\">les</span> époques et les sociétés</li>\n  <li>Production différenciée des <span class=\"kw-def\">normes corporelles</span> selon <span class=\"kw-clinique\">les</span> cultes</li>\n</ul>\n\n<h4 class=\"kw-def\">Genre</h4>\n<p>Le <strong><span class=\"kw-def\">genre</span></strong> renvoie à la <span class=\"kw-def\">construction sociale</span> de l'identité, et pas uniquement à la <span class=\"kw-def\">différenciation biologique</span> des sexes.</p>\n\n<h4 class=\"kw-def\">Trois fonctions sociologiques du corps (Bourdieu)</h4>\n<ul>\n  <li>Fonction de <strong><span class=\"kw-def\">mémoire</span></strong></li>\n  <li>Fonction d'<strong><span class=\"kw-def\">apprentissage des habitudes de classe</span></strong></li>\n  <li>Fonction de <strong><span class=\"kw-def\">marqueur de position sociale</span></strong></li>\n</ul>\n<div class=\"callout callout-info\">Le <span class=\"kw-def\">corps</span> est un <strong>témoin des inégalités</strong> entre classes sociales : <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">habitudes alimentaires</span> et le <span class=\"kw-etio\">type de travail</span> ne façonnent pas les corps de la même manière.</div>","frequence":0},{"id":"10-2","rang":"B","rubrique":"Définition","titre":"Connaître l’impact des différentes maladies sur l’expérience du corps (changements de l’identité, image du corps, image et estime de soi, répercussions relationnelles)","contenu":"<p>L'<strong><span class=\"kw-def\">expérience corporelle</span></strong> est la <strong><span class=\"kw-def\">conscience immédiate et intime de notre propre corps</span></strong>. Elle est strictement personnelle :</p>\n<ul>\n  <li>Seul l'individu peut en faire l'<span class=\"kw-def\">expérience de l'intérieur</span></li>\n  <li>La <span class=\"kw-def\">perception</span> de son propre corps diffère de celle du corps d'autrui</li>\n</ul>\n\n<h4 class=\"kw-def\">Quatre axes d'impact de la maladie</h4>\n<ul>\n  <li>Changements de l'<strong><span class=\"kw-def\">identité</span></strong></li>\n  <li>Modification de l'<strong><span class=\"kw-def\">image du corps</span></strong></li>\n  <li>Atteinte de l'<strong><span class=\"kw-def\">image et de l'estime de soi</span></strong></li>\n  <li><strong><span class=\"kw-def\">Répercussions relationnelles</span></strong></li>\n</ul>\n\n<h4 class=\"kw-def\">La maladie exacerbe l'expérience du corps</h4>\n<p>La <strong><span class=\"kw-etio\">maladie</span></strong> exacerbe l'expérience corporelle et crée une <strong><span class=\"kw-def\">dissension</span></strong> entre deux points de vue :</p>\n<table >\n  <thead><tr><th>Perception du soignant</th><th>Perception du soigné</th></tr></thead>\n  <tbody>\n    <tr><td>Maladie = <span class=\"kw-def\">phénomène physique</span> nécessitant une <span class=\"kw-def\">intervention médicale</span></td><td>Maladie ayant un <span class=\"kw-clinique\">impact sur la vie entière</span></td></tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-warn\">⚠️ Le malade est en <strong>quête de sens</strong> : la maladie suscite des <span class=\"kw-clinique\">sentiments</span> (<span class=\"kw-clinique\">honte</span>, <span class=\"kw-clinique\">peur</span>) ou des <span class=\"kw-clinique\">comportements</span> (<span class=\"kw-clinique\">reproches</span>) qui <span class=\"kw-alerte\">augmentent la souffrance</span>.</div>\n\n<h4 class=\"kw-def\">Impact sur le corps (exemple de la douleur)</h4>\n<p>L'analyse de l'<strong><span class=\"kw-clinique\">expérience de la douleur</span></strong> montre comment la maladie modifie en profondeur le rapport au corps :</p>\n<ul>\n  <li>Atteinte du <strong><span class=\"kw-def\">sentiment d'identité</span></strong></li>\n  <li><strong><span class=\"kw-def\">Transformation en profondeur</span></strong> du patient</li>\n  <li>Changements de <span class=\"kw-clinique\">comportement de l'entourage</span> (répercussions relationnelles)</li>\n  <li>Retentissement <span class=\"kw-clinique\">physique</span> et <span class=\"kw-clinique\">moral</span></li>\n  <li><span class=\"kw-clinique\">Altération de toutes les activités</span></li>\n</ul>\n\n<div class=\"callout callout-info\">La maladie peut ainsi altérer durablement l'<span class=\"kw-def\">estime de soi</span> et l'<span class=\"kw-def\">image du corps</span>, avec des <span class=\"kw-clinique\">répercussions relationnelles</span> sur l'entourage.</div>","frequence":0},{"id":"10-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître la place du corps dans les pratiques cliniques (données personnelles, regard médical, palpation, imagerie, analyses biologiques, etc.)","contenu":"<p>L'<strong><span class=\"kw-def\">essor des dispositifs techniques</span></strong> en médecine a transformé la place du corps dans la <strong><span class=\"kw-def\">pratique clinique</span></strong> :</p>\n<ul>\n  <li>Le <span class=\"kw-bio\">thermomètre</span></li>\n  <li>Le <span class=\"kw-clinique\">stéthoscope</span></li>\n  <li>L'<span class=\"kw-imagerie\">imagerie médicale</span></li>\n  <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">analyses biologiques</span></li>\n</ul>\n\n<h4 class=\"kw-def\">Conséquences sur le regard médical</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Redéfinition</span></strong> de la manière de voir et de concevoir <span class=\"kw-clinique\">les</span> maladies</li>\n  <li>Le <strong><span class=\"kw-def\">soignant</span></strong> devient <span class=\"kw-def\">observateur</span>, le <strong><span class=\"kw-def\">patient</span></strong> devient <span class=\"kw-def\">observé</span></li>\n  <li>Redéfinition des <span class=\"kw-def\">frontières entre intérieur et extérieur</span> du corps</li>\n  <li>Transformation de la <span class=\"kw-def\">matérialité du corps</span> en <span class=\"kw-bio\">variables</span>, <span class=\"kw-imagerie\">images</span> et <span class=\"kw-bio\">données</span></li>\n</ul>\n\n<div class=\"callout callout-warn\">⚠️ Cette objectivation peut être <span class=\"kw-alerte\">réductionniste</span> : la <span class=\"kw-def\">terminologie médicale</span> propre induit une <strong>mise à distance</strong> et un <span class=\"kw-alerte\">écart entre le vécu subjectif</span> du patient et la manière dont la médecine objective son corps.</div>\n\n<h4 class=\"kw-def\">Corps-sujet <span class=\"kw-bio\">vs</span> corps-objet (sciences humaines)</h4>\n<p><span class=\"kw-clinique\">Les</span> sciences humaines distinguent le <strong><span class=\"kw-def\">corps-sujet</span></strong> et le <strong><span class=\"kw-def\">corps-objet</span></strong> ; cette distinction permet de <strong>relativiser</strong> les connaissances sur le corps sans <span class=\"kw-alerte\">réductionnisme</span>.</p>\n<table >\n  <thead><tr><th>Corps-sujet</th><th>Corps-objet</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>Corps subjectif :</strong> <span class=\"kw-def\">substrat psychophysiologique</span> de l'expérience individuelle du corps<br><strong>Corps du sujet :</strong> <span class=\"kw-def\">corporéité</span> sur laquelle s'exerce l'action du sujet humain</td>\n      <td>Simple corps parmi <span class=\"kw-clinique\">les</span> corps, <span class=\"kw-def\">impersonnel</span> ; régi par des <span class=\"kw-def\">lois naturelles</span> ; dépourvu de <span class=\"kw-def\">caractéristiques spécifiquement humaines</span> ; objet d'action ou de contemplation</td>\n    </tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-danger\">⚠️ Le corps <strong>ne peut être réduit</strong> ni à une <span class=\"kw-def\">batterie d'organes</span>, ni à un ensemble de <span class=\"kw-bio\">chiffres</span> ou d'<span class=\"kw-imagerie\">images de laboratoire</span>, ni au seul <span class=\"kw-clinique\">récit</span> que le patient fait de sa propre vie.</div>","frequence":0}],"astuces":[],"strategie":{},"cards":[{"i":"0ae612321e70","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Quelle définition le concept de genre prend-il dans l'étude du corps en SHS ?","a":"<p>Le genre renvoie à la <strong>construction sociale de l'identité</strong>, et non uniquement à la différenciation biologique des sexes.</p>"},{"i":"4396f7e48345","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Comment l'alimentation est-elle considérée comme un fait social en SHS ?","a":"<p>L'alimentation est au cœur d'un dispositif <strong>social, symbolique et économique</strong>. L'acte de manger reconstruit les logiques sociales et les identités d'un groupe, comme en témoignent :</p><ul><li>Les <strong>interdits alimentaires</strong> dans les traditions religieuses.</li><li>Les <strong>régimes de santé</strong> liés aux âges de la vie.</li><li>L'impact de la nourriture sur la <strong>sphère émotionnelle et affective</strong>.</li><li>L'importance de la <strong>gastronomie</strong> dans les interactions sociales.</li></ul>"},{"i":"498a70559777","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Comment les normes esthétiques du corps sont-elles construites socialement ?","a":"<p>Les normes esthétiques sont le reflet de <strong>différences sociales et culturelles</strong>. Elles sont sujettes à des <strong>transformations volontaires</strong> (tatouages, piercings, scarifications) dont les fonctions varient selon les époques et les sociétés. Il n'existe pas de norme corporelle universelle, mais une <strong>construction sociale variable</strong> selon les cultures et les époques.</p>"},{"i":"8e300707d6f9","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Selon Bourdieu, quelles sont les trois fonctions sociologiques du corps ?","a":"<ul><li>Fonction de <strong>mémoire</strong>.</li><li>Fonction d'<strong>apprentissage des habitudes de classe</strong>.</li><li>Fonction de <strong>marqueur de position sociale</strong>.</li></ul>"},{"i":"d52f959b1ffc","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Quelle est la définition du corps en sciences humaines et sociales (SHS) ?","a":"<p>En SHS, le corps est un objet d'étude <strong>multidimensionnel</strong> dont la représentation est une <strong>construction sociale</strong>, s'adaptant aux traditions culturelles et au milieu naturel.</p>"},{"i":"d952e8b9ca2a","n":10,"o":"10-1","u":"Définition","t":"Connaître les principales dimensions humaines du corps (alimentation, activité physique, genre, procréation, normes esthétiques)","q":"Quelles sont les cinq principales dimensions humaines du corps étudiées en SHS ?","a":"<ul><li><strong>Alimentation</strong> : choix et manière de se nourrir.</li><li><strong>Activité physique</strong> : rapport au mouvement et à la sédentarité.</li><li><strong>Genre</strong> : question de l'identité et de l'identité sexuée.</li><li><strong>Procréation</strong> : rapport à la reproduction.</li><li><strong>Normes esthétiques</strong> : standards de beauté et règles corporelles.</li></ul>"}]};